export const formats=['свадьба','той','корпоратив','конференция','юбилей','день рождения'];
export const languages=['русский','казахский','английский'];
export const reasonLabels={busy:'заняты на эту дату',over_budget:'стартовая цена выше бюджета',wrong_format:'не работают с этим форматом',wrong_language:'не работают на этом языке',too_short:'не могут работать столько часов'};
function grams(text){const result=new Map();for(const word of text.toLowerCase().match(/[\p{L}\p{N}_]+/gu)||[]){const padded=` ${word} `;for(const size of [3,4,5])for(let i=0;i<=padded.length-size;i++){const key=padded.slice(i,i+size);result.set(key,(result.get(key)||0)+1);}}return result;}
class DescriptionIndex{
 constructor(texts){const documents=texts.map(grams),freq=new Map();for(const doc of documents)for(const k of doc.keys())freq.set(k,(freq.get(k)||0)+1);this.idf=new Map([...freq].map(([k,v])=>[k,Math.log((texts.length+1)/(v+1))+1]));this.vectors=documents.map(d=>this.vector(d));}
 vector(counts){const v=new Map();for(const [k,n] of counts)if(this.idf.has(k))v.set(k,(1+Math.log(n))*this.idf.get(k));const norm=Math.sqrt([...v.values()].reduce((s,n)=>s+n*n,0));return new Map([...v].map(([k,n])=>[k,n/norm]));}
 similarities(query){const q=this.vector(grams(query));return this.vectors.map(v=>[...q].reduce((s,[k,n])=>s+n*(v.get(k)||0),0));}
}
function query(r){return r.brief?`${r.brief.replace(new RegExp(r.category.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),' ')} ${r.event_format}`.trim():`${r.category} ${r.event_format}`;}
export function quoteCandidates(p){const fragments=p.description.split(/(?<=[.!?])\s+|(?<=[.!?])(?=[A-ZА-ЯЁ])|\n+|•/u).map(s=>s.trim()).filter(Boolean);let candidates=fragments.filter(s=>s.length>=12);if(!candidates.length)candidates=fragments;const complete=candidates.filter(s=>s.length<=280);if(complete.length)candidates=complete;return [...new Set(candidates.map(s=>s.length<=280?s:s.slice(0,280).replace(/ +[^ ]*$/,'').trim()).filter(Boolean))];}
export function hasNegativeBrief(r){return /(?:^|[^\p{L}\p{N}_])(?:без|не|никаких|никакого|никакой|исключить|исключая)(?=$|[^\p{L}\p{N}_])/u.test((r.brief||'').toLowerCase());}
export function evidenceOptions(p,r){const excerpts=quoteCandidates(p),negative=hasNegativeBrief(r),brief=negative?'':r.brief;let q=brief?query(r):r.event_format;if(brief)for(const [stem,words] of Object.entries({'форум':'форум конференц бизнес','делов':'делов конференц бизнес','спокой':'спокой интеллигент ненавязчив мягк тонк юмор манер','традиц':'традиц той казах','креатив':'креатив оригинальн необыч','эмоц':'эмоц атмосфер искрен естеств динамик момент','репортаж':'репортаж незаметн момент событ'}))if(brief.toLowerCase().includes(stem))q+=' '+words;const scores=new DescriptionIndex(excerpts).similarities(q),boilerplate=/топ[-\s]?\d|лучши[йемх]|идеальн|приветств|с уважением|всегда ваш|делает уровень|не сомнева/i,concrete=/\d|опыт|юмор|манер|подач|сценар|интерактив|импровиз|репортаж|эмоц|съ[её]м|флорист|цветоч|оформ|оборуд|банкет|террас|панорам|язык|формат|конференц|тимбилдинг|стиль|танц|развлеч|реч|незаметн|атмосфер/i;return excerpts.map((text,i)=>({text,i,score:scores[i],generic:Number(boilerplate.test(text)),specific:Number(!concrete.test(text))})).sort((a,b)=>a.generic-b.generic||a.specific-b.specific||b.score-a.score||a.i-b.i).slice(0,3).map(x=>x.text);}
export function localQuotes(profiles,r){const result=new Map(),used=new Set();for(const p of profiles){const options=evidenceOptions(p,r),quote=options.find(q=>!used.has(q))||options[0];result.set(p.id,quote);used.add(quote);}return result;}
export function localQuote(p,r){return localQuotes([p],r).get(p.id);}
const normalize=s=>s.toLowerCase().trim().replace(/\s+/g,' ');
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s&&s>='2026-09-23'&&s<='2026-12-31';}
export function validateCatalogue(catalogue){if(!Array.isArray(catalogue)||catalogue.length!==66||new Set(catalogue.map(p=>p.id)).size!==66)throw Error('Ожидались 66 профилей с уникальными ID.');for(const p of catalogue){for(const key of ['id','name','city','description'])if(typeof p[key]!=='string'||!p[key].trim())throw Error('В каталоге есть незаполненные поля.');for(const key of ['categories','event_formats','languages'])if(!Array.isArray(p[key])||!p[key].length||p[key].some(v=>typeof v!=='string'||!v.trim()))throw Error('Некорректные варианты в каталоге.');if(!Number.isSafeInteger(p.price_from_kzt)||p.price_from_kzt<=0||p.max_hours!==null&&(!Number.isFinite(p.max_hours)||p.max_hours<=0))throw Error('Некорректная цена или длительность в каталоге.');if(p.event_formats.some(v=>!formats.includes(v))||p.languages.some(v=>!languages.includes(v))||!Array.isArray(p.busy_dates)||p.busy_dates.some(v=>!validDate(v)))throw Error('Некорректные форматы, языки или даты каталога.');for(const key of ['synthetic','city_imputed','price_imputed'])if(typeof p[key]!=='boolean')throw Error('Некорректные признаки происхождения данных.');}return catalogue;}
export function catalogueOptions(catalogue){const cities=[...new Set(catalogue.map(p=>p.city))].sort();return {cities,categories_by_city:Object.fromEntries(cities.map(city=>[city,[...new Set(catalogue.filter(p=>p.city===city).flatMap(p=>p.categories))].sort()])),event_formats:[...new Set(catalogue.flatMap(p=>p.event_formats))].sort(),languages:[...new Set(catalogue.flatMap(p=>p.languages))].sort(),calendar_start:'2026-09-23',calendar_end:'2026-12-31'};}
export function validateRequest(input,catalogue){const r={...input};for(const k of ['city','category','event_format','date','language','brief'])r[k]=typeof r[k]==='string'?r[k].trim():'';for(const k of ['city','category','brief'])r[k]=r[k].replace(/\s+/g,' ');if(r.city.length>100||r.category.length>100)throw Error('Название города или категории слишком длинное.');if(typeof r.budget_kzt==='boolean'||typeof r.duration_hours==='boolean')throw Error('Укажите числовые значения.');r.budget_kzt=Number(r.budget_kzt);r.duration_hours=r.duration_hours===''||r.duration_hours==null?null:Number(r.duration_hours);r.city=catalogue.find(p=>normalize(p.city)===normalize(r.city))?.city;r.category=catalogue.flatMap(p=>p.categories).find(c=>normalize(c)===normalize(r.category));r.event_format=normalize(r.event_format);r.language=normalize(r.language);if(!r.city)throw Error('Выберите город из каталога.');if(!r.category)throw Error('Выберите категорию из каталога.');if(!formats.includes(r.event_format))throw Error('Выберите формат мероприятия.');if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||r.date<'2026-09-23'||r.date>'2026-12-31')throw Error('Выберите дату с 23.09.2026 по 31.12.2026.');if(!Number.isSafeInteger(r.budget_kzt)||r.budget_kzt<=0)throw Error('Укажите положительный бюджет в тенге.');if(r.duration_hours!==null&&(!Number.isFinite(r.duration_hours)||r.duration_hours<=0))throw Error('Длительность должна быть больше нуля.');if(r.language&&!languages.includes(r.language))throw Error('Выберите язык из списка.');if(r.brief.length>500)throw Error('Пожелания: не больше 500 символов.');return r;}
export function createMatcher(catalogue){validateCatalogue(catalogue);const index=new DescriptionIndex(catalogue.map(p=>p.description));return input=>{const r=validateRequest(input,catalogue),category=catalogue.filter(p=>p.city===r.city&&p.categories.includes(r.category));if(!category.length)return {status:'category_absent',cards:[],allEligible:[],reasons:{},eligible:0,total:0,request:r,ai_mode:'not_used'};const reasons=Object.fromEntries(Object.keys(reasonLabels).map(k=>[k,0]));const eligible=category.filter(p=>{const failures={busy:p.busy_dates.includes(r.date),over_budget:p.price_from_kzt>r.budget_kzt,wrong_format:!p.event_formats.includes(r.event_format),wrong_language:!!r.language&&!p.languages.includes(r.language),too_short:r.duration_hours!==null&&p.max_hours!==null&&p.max_hours<r.duration_hours};for(const [k,v] of Object.entries(failures))if(v)reasons[k]++;return !Object.values(failures).some(Boolean);});const scores=index.similarities(query(r)),scoreById=new Map(catalogue.map((p,i)=>[p.id,scores[i]]));eligible.sort((a,b)=>scoreById.get(b.id)-scoreById.get(a.id)||a.price_from_kzt-b.price_from_kzt||(a.id<b.id?-1:a.id>b.id?1:0));const selected=eligible.slice(0,3),quotes=localQuotes(selected,r);return {status:eligible.length?'matched':'no_eligible',cards:selected.map(p=>({...p,evidence_quote:quotes.get(p.id)})),allEligible:eligible,reasons,eligible:eligible.length,total:category.length,request:r,ai_mode:eligible.length?'fallback':'not_used'};};}
